1	import { finding, lineOf } from './finding.mjs';
2	
3	// The app's whole behaviour is one ordered colour cycle, and lib/main.dart spells
4	// it out in three places that a human has to keep aligned by hand: the `_cycle`
5	// list, the parallel `_colorNames` labels the button writes into the greeting, and
6	// the theme's `ColorScheme.fromSeed` seed (which must be the colour the app starts
7	// on). Editing one and not the others compiles, and — because `_colorNames` is
8	// indexed by the same `_colorIndex` — ships a screen that says "hello world red"
9	// on a purple background. That is exactly the class of drift a regex can catch
10	// before `flutter test` is even booted.
11	const CYCLE = /_cycle\s*=\s*<Color>\[([\s\S]*?)\]/;
12	const NAMES = /_colorNames\s*=\s*<String>\[([\s\S]*?)\]/;
13	const SEED = /ColorScheme\.fromSeed\(\s*seedColor:\s*Colors\.(\w+)/;
14	const FOREGROUND = /foregroundColor:\s*([A-Za-z_][\w.]*)/;
15	
16	const APP = 'lib/main.dart';
17	
18	const rule = {
19	  id: 'hello-world-flutter/color-cycle-lockstep',
20	  severity: 'blocking',
21	  description: 'lib/main.dart declares the colour cycle once: _cycle, _colorNames and the theme seed agree',
22	  doc: '.claudinite/local/packs/hello-world-flutter/RULES.md',
23	  why: 'the label is indexed by the cycle index, so a cycle edit that misses _colorNames or the seed ships a screen whose text names the wrong colour',
24	
25	  run(ctx) {
26	    const text = ctx.read(APP);
27	    if (text === null) return [];
28	
29	    const cycleBody = CYCLE.exec(text);
30	    const namesBody = NAMES.exec(text);
31	    // No cycle declared at all — a different app shape, nothing to keep in step.
32	    if (!cycleBody || !namesBody) return [];
33	
34	    const colors = [...cycleBody[1].matchAll(/Colors\.(\w+)/g)].map((m) => m[1]);
35	    const names = [...namesBody[1].matchAll(/'([^']*)'/g)].map((m) => m[1]);
36	    const namesLine = lineOf(text, NAMES);
37	    const out = [];
38	
39	    if (colors.length !== names.length) {
40	      out.push(finding(rule, {
41	        file: APP,
42	        line: namesLine,
43	        what: `_cycle has ${colors.length} colours but _colorNames has ${names.length} labels`,
44	        fix: 'add or remove the matching _colorNames entry so the two lists stay index-for-index',
45	      }));
46	    }
47	
48	    for (let i = 0; i < Math.min(colors.length, names.length); i += 1) {
49	      if (colors[i].toLowerCase() !== names[i].toLowerCase()) {
50	        out.push(finding(rule, {
51	          file: APP,
52	          line: namesLine,
53	          what: `_cycle[${i}] is Colors.${colors[i]} but _colorNames[${i}] is '${names[i]}'`,
54	          fix: `name entry ${i} '${colors[i].toLowerCase()}' — the label is looked up by the cycle index`,
55	        }));
56	      }
57	    }
58	
59	    const seed = SEED.exec(text);
60	    if (seed && colors.length && seed[1] !== colors[0]) {
61	      out.push(finding(rule, {
62	        file: APP,
63	        line: lineOf(text, SEED),
64	        what: `the theme seeds from Colors.${seed[1]} but the app starts on _cycle[0] = Colors.${colors[0]}`,
65	        fix: `seed the ColorScheme from Colors.${colors[0]}, the first entry of _cycle`,
66	      }));
67	    }
68	
69	    // The button's foreground must track the background, not a pinned literal —
70	    // widget_test.dart asserts exactly that after every press.
71	    const foreground = FOREGROUND.exec(text);
72	    if (foreground && foreground[1] !== '_backgroundColor') {
73	      out.push(finding(rule, {
74	        file: APP,
75	        line: lineOf(text, FOREGROUND),
76	        what: `the button's foregroundColor is pinned to ${foreground[1]} instead of following _backgroundColor`,
77	        fix: 'set foregroundColor: _backgroundColor so the label re-colours with the cycle',
78	      }));
79	    }
80	
81	    return out;
82	  },
83	};
84	
85	export default rule;
