1	// The finding shape the checks engine renders, built locally on purpose: a local
2	// pack's rule modules must load without the gitignored shared mount, so they
3	// never import `engine/checks/helpers/findings.mjs`. Keep this in step with that
4	// helper's return shape.
5	export const finding = (rule, { file, line = null, what, fix }) => ({
6	  rule: rule.id,
7	  severity: rule.severity,
8	  file,
9	  line,
10	  what,
11	  why: rule.why,
12	  fix,
13	  doc: rule.doc,
14	});
15	
16	// Python source with its prose blanked out — `#` comments and triple-quoted
17	// docstrings become empty lines, so a rule scans what the interpreter runs and not
18	// what the file says ABOUT running it. Line count is preserved so `lineOf` still
19	// points at the real line. Necessary here because this repo's scripts document the
20	// very patterns they forbid ("do NOT reimplement this with bash `setsid ... &`"),
21	// and a naive substring scan would flag the warning as the violation.
22	export const pythonCode = (text) => {
23	  let delimiter = null;
24	  return text.split('\n').map((raw) => {
25	    let line = raw;
26	    if (delimiter) {
27	      if (!line.includes(delimiter)) return '';
28	      line = line.slice(line.indexOf(delimiter) + 3);
29	      delimiter = null;
30	    }
31	    for (const d of ['"""', "'''"]) {
32	      const open = line.indexOf(d);
33	      if (open === -1) continue;
34	      const close = line.indexOf(d, open + 3);
35	      if (close === -1) { delimiter = d; line = line.slice(0, open); }
36	      else line = line.slice(0, open) + line.slice(close + 3);
37	    }
38	    const hash = line.indexOf('#');
39	    return hash === -1 ? line : line.slice(0, hash);
40	  }).join('\n');
41	};
42	
43	// 1-based line number of the first line matching `pattern`, or null.
44	export const lineOf = (text, pattern) => {
45	  const lines = text.split('\n');
46	  for (let i = 0; i < lines.length; i += 1) if (pattern.test(lines[i])) return i + 1;
47	  return null;
48	};
